+const navToggle = document.querySelector(".nav-toggle");
+const navLinks = document.querySelector(".nav-links");
+const cartCount = document.querySelector("[data-cart-count]");
+const toast = document.querySelector("[data-toast]");
+const countdown = document.querySelector("[data-countdown]");
+const newsletterForm = document.querySelector(".newsletter-form");
+
+let cartItems = 0;
+let toastTimer;
+let dealSecondsRemaining = 12 * 60 * 60;
+
+function showToast(message) {
+  toast.textContent = message;
+  toast.classList.add("is-visible");
+  clearTimeout(toastTimer);
+  toastTimer = setTimeout(() => toast.classList.remove("is-visible"), 2600);
+}
+
+function formatTime(totalSeconds) {
+  const hours = String(Math.floor(totalSeconds / 3600)).padStart(2, "0");
+  const minutes = String(Math.floor((totalSeconds % 3600) / 60)).padStart(2, "0");
+  const seconds = String(totalSeconds % 60).padStart(2, "0");
+
+  return `${hours}:${minutes}:${seconds}`;
+}
+
+function updateCountdown() {
+  countdown.textContent = formatTime(dealSecondsRemaining);
+  dealSecondsRemaining = Math.max(0, dealSecondsRemaining - 1);
+}
+
+navToggle.addEventListener("click", () => {
+  const isOpen = navLinks.classList.toggle("is-open");
+  navToggle.setAttribute("aria-expanded", String(isOpen));
+});
+
+document.querySelectorAll(".add-to-cart").forEach((button) => {
+  button.addEventListener("click", () => {
+    cartItems += 1;
+    cartCount.textContent = cartItems;
+    showToast(`${button.dataset.product} added to your bag.`);
+  });
+});
+
+newsletterForm.addEventListener("submit", (event) => {
+  event.preventDefault();
+  const email = new FormData(newsletterForm).get("email") || "your inbox";
+  showToast(`Welcome to the night list, ${email}.`);
+  newsletterForm.reset();
+});
+
+updateCountdown();
+setInterval(updateCountdown, 1000);
